import React from "react";

interface Car {
  id: number;
  brand: string;
  model: string;
  yearOfManufacture: number;
  color: string;
  price: number;
  description: string;
  imageUrls: string[];
}

function CarList() {
  const [cars, setCars] = React.useState<Car[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    fetch('http://localhost:8080/cars')
      .then(response => {
        if (!response.ok) {
          throw new Error('Ошибка при загрузке данных');
        }
        return response.json();
      })
      .then((data: Car[]) => {
        setCars(data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <div>Загрузка...</div>;
  if (error) return <div>Ошибка: {error}</div>;

  return (
    <div className="car-list">
      {cars.map(car => (
        <div key={car.id} className="car-card">
          <div className="car-image">
            {car.imageUrls && car.imageUrls.length > 0 ? (
              <img src={car.imageUrls[0]} alt={`${car.brand} ${car.model}`} />
            ) : (
              <div className="no-image">Нет изображения</div>
            )}
          </div>
          <div className="car-info">
            <h3>{car.brand} {car.model} ({car.yearOfManufacture})</h3>
            <p><strong>Цвет:</strong> {car.color}</p>
            <p><strong>Цена:</strong> ${car.price}</p>
            <p><strong>Описание:</strong> {car.description}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

export default CarList;
